using System.Globalization;
using System.IO;
using System.Text;
using System.Text.RegularExpressions;
using System.Xml.Linq;
namespace RedroBridgeMaker;
static class VectorParser
{
 static readonly Regex SvgTokenRegex=new(@"[MLHVZmlhvz]|[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?",RegexOptions.Compiled);
 static double N(string s)=>double.Parse(s,NumberStyles.Float,CultureInfo.InvariantCulture);
 public static DocumentModel Load(string file)=>System.IO.Path.GetExtension(file).ToLowerInvariant() switch{".eps"=>Eps(file),".svg"=>Svg(file),".pdf"=>Pdf(file),_=>throw new NotSupportedException("Use PDF, EPS or SVG.")};
 static DocumentModel Svg(string file){var d=new DocumentModel();var x=XDocument.Load(file);foreach(var el in x.Descendants().Where(e=>e.Name.LocalName=="path")){var tokens=SvgTokenRegex.Matches((string?)el.Attribute("d")??"");int i=0;double cx=0,cy=0;PathModel? p=null;while(i<tokens.Count){char c=tokens[i++].Value[0];if(c is 'Z' or 'z'){if(p!=null)p.Closed=true;continue;}int needed=c is 'H' or 'h' or 'V' or 'v'?1:2;if(i+needed>tokens.Count)break;if(c is 'H' or 'h'){double x1=N(tokens[i++].Value);double nx=c=='h'?cx+x1:x1;if(p!=null)p.Segments.Add(new Seg(new Pt(cx,cy),new Pt(nx,cy)));if(p!=null)p.Points.Add(new Pt(nx,cy));cx=nx;continue;}if(c is 'V' or 'v'){double y1=N(tokens[i++].Value);double ny=c=='v'?cy+y1:y1;if(p!=null)p.Segments.Add(new Seg(new Pt(cx,cy),new Pt(cx,ny)));if(p!=null)p.Points.Add(new Pt(cx,ny));cy=ny;continue;}double a=N(tokens[i++].Value);double b=N(tokens[i++].Value);double nx2=c is 'm' or 'l'?cx+a:a;double ny2=c is 'm' or 'l'?cy+b:b;if(c is 'M' or 'm'){p=new PathModel();p.Points.Add(new Pt(nx2,ny2));d.Paths.Add(p);}else if(p!=null){var q=new Pt(nx2,ny2);p.Segments.Add(new Seg(new Pt(cx,cy),q));p.Points.Add(q);}cx=nx2;cy=ny2;}}return d;}
 static DocumentModel Eps(string file){var d=new DocumentModel();var text=File.ReadAllText(file);var tok=Regex.Matches(text,@"[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?|/[A-Za-z]+|[A-Za-z]+");var st=new Stack<double>();PathModel? p=null;var cur=new Pt(0,0);foreach(Match m in tok){if(double.TryParse(m.Value,NumberStyles.Float,CultureInfo.InvariantCulture,out var n)){st.Push(n);continue;}var op=m.Value.TrimStart('/');if(op=="moveto"&&st.Count>=2){var y=st.Pop();var xx=st.Pop();p=new PathModel();cur=new Pt(xx,y);p.Points.Add(cur);d.Paths.Add(p);}else if(op=="lineto"&&st.Count>=2&&p!=null){var y=st.Pop();var xx=st.Pop();var q=new Pt(xx,y);p.Segments.Add(new Seg(cur,q));p.Points.Add(q);cur=q;}else if(op=="closepath"&&p!=null)p.Closed=true;else if(op=="newpath")p=null;else if(op=="curveto"&&st.Count>=6&&p!=null){var y3=st.Pop();var x3=st.Pop();st.Pop();st.Pop();st.Pop();st.Pop();var q=new Pt(x3,y3);p.Segments.Add(new Seg(cur,q));p.Points.Add(q);cur=q;}}return d;}
 static DocumentModel Pdf(string file){var d=new DocumentModel();var raw=Encoding.ASCII.GetString(File.ReadAllBytes(file));foreach(Match m in Regex.Matches(raw,@"stream\r?\n(.*?)\r?\nendstream",RegexOptions.Singleline))ParsePdfStream(m.Groups[1].Value,d);return d;}
 static void ParsePdfStream(string s,DocumentModel d){var tok=Regex.Matches(s,@"[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?|[A-Za-z]+");var st=new Stack<double>();PathModel? p=null;var cur=new Pt(0,0);foreach(Match m in tok){if(double.TryParse(m.Value,NumberStyles.Float,CultureInfo.InvariantCulture,out var n)){st.Push(n);continue;}var op=m.Value;if(op=="m"&&st.Count>=2){var y=st.Pop();var x=st.Pop();p=new PathModel();cur=new Pt(x,y);p.Points.Add(cur);d.Paths.Add(p);}else if(op=="l"&&st.Count>=2&&p!=null){var y=st.Pop();var x=st.Pop();var q=new Pt(x,y);p.Segments.Add(new Seg(cur,q));p.Points.Add(q);cur=q;}else if(op=="re"&&st.Count>=4){var h=st.Pop();var w=st.Pop();var y=st.Pop();var x=st.Pop();p=new PathModel();var a=new Pt(x,y);var b=new Pt(x+w,y);var c=new Pt(x+w,y+h);var e=new Pt(x,y+h);p.Points.AddRange(new[]{a,b,c,e,a});p.Segments.AddRange(new[]{new Seg(a,b),new Seg(b,c),new Seg(c,e),new Seg(e,a)});p.Closed=true;cur=a;d.Paths.Add(p);}else if(op=="h"&&p!=null)p.Closed=true;else if(op=="c"&&st.Count>=6&&p!=null){var y3=st.Pop();var x3=st.Pop();st.Pop();st.Pop();st.Pop();st.Pop();var q=new Pt(x3,y3);p.Segments.Add(new Seg(cur,q));p.Points.Add(q);cur=q;}}}
}